CREATE
OR REPLACE FUNCTION generate_customer_code(company_name VARCHAR)
RETURNS TEXT AS $$
DECLARE
format TEXT;
    next_value
INTEGER;
    customer_code
TEXT;
    formatted_value
TEXT;
BEGIN
SELECT format_customer_code
INTO format
FROM customer_code_formats
WHERE company = company_name LIMIT 1;

IF
format IS NULL THEN
        RAISE EXCEPTION 'No format found for company: %', company_name;
END IF;

SELECT current_value
INTO next_value
FROM customer_code_formats
WHERE company = company_name LIMIT 1;

UPDATE customer_code_formats
SET current_value = current_value + 1
WHERE company = company_name;

formatted_value
:= LPAD(next_value::TEXT, 6, '0');

    customer_code
:= REPLACE(format, '%06d', formatted_value);

RETURN customer_code;
END;
$$
LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_before_insert_customer ON customer;

CREATE
OR REPLACE FUNCTION before_insert_customer()
RETURNS TRIGGER AS $$
BEGIN
    NEW.customer_code
:= generate_customer_code(NEW.company);
RETURN NEW;
END;
$$
LANGUAGE plpgsql;

CREATE TRIGGER trg_before_insert_customer
    BEFORE INSERT
    ON customer
    FOR EACH ROW
    EXECUTE FUNCTION before_insert_customer();
